CREATE TABLE IF NOT EXISTS richo_ai_configurations(id uuid PRIMARY KEY,agent_id text NOT NULL,provider text NOT NULL,model text NOT NULL,prompt_version text NOT NULL,parameters jsonb NOT NULL DEFAULT '{}'::jsonb,environment text NOT NULL,status text NOT NULL DEFAULT 'candidate' CHECK(status IN('candidate','canary','active','retired','rolled_back')),correlation_id text,created_at timestamptz NOT NULL DEFAULT now(),promoted_at timestamptz);
CREATE TABLE IF NOT EXISTS richo_ai_eval_suites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,description text,golden_dataset_version text NOT NULL,metrics jsonb NOT NULL,thresholds jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_ai_eval_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),configuration_id uuid NOT NULL REFERENCES richo_ai_configurations(id) ON DELETE CASCADE,suite_id uuid REFERENCES richo_ai_eval_suites(id) ON DELETE SET NULL,quality numeric(10,6),grounding numeric(10,6),hallucination_rate numeric(10,6),cost numeric(18,8),latency_ms numeric(18,4),passed boolean NOT NULL,failures jsonb NOT NULL DEFAULT '[]'::jsonb,details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_ai_canary_releases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),configuration_id uuid NOT NULL REFERENCES richo_ai_configurations(id),baseline_configuration_id uuid REFERENCES richo_ai_configurations(id),traffic_pct numeric(6,3) NOT NULL DEFAULT 5,status text NOT NULL DEFAULT 'running' CHECK(status IN('running','promoted','rolled_back','paused')),metrics jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS richo_ai_config_agent_idx ON richo_ai_configurations(agent_id,environment,status);
